CREATE POLICY "anexos_storage_select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'anexos' AND private.is_membro(auth.uid()));
CREATE POLICY "anexos_storage_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'anexos' AND private.is_membro(auth.uid()));
CREATE POLICY "anexos_storage_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'anexos' AND private.is_membro(auth.uid())) WITH CHECK (bucket_id = 'anexos' AND private.is_membro(auth.uid()));
CREATE POLICY "anexos_storage_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'anexos' AND private.pode_excluir(auth.uid()));